    public static string Get(string key, string locale, params object[] args)
    {
        var index = locale.StartsWith("it", StringComparison.OrdinalIgnoreCase) ? 1
            : locale.StartsWith("zh", StringComparison.OrdinalIgnoreCase) ? 0 : 2;
        if (!Messages.TryGetValue(key, out var translations))
            return string.Format(CultureInfo.CurrentCulture, Messages["UnknownCode"][index], key);
        return args.Length == 0 ? translations[index] : string.Format(CultureInfo.CurrentCulture, translations[index], args);
    }

    public static string Component(string id, string locale) => id is "Outlook" or "Lync" ? Get(id, locale) : id;
}
